"""HTML/CSS from the supplied heatmapper; contact/email removed."""

def heatmap_html(paragraph_html):
    return f'\n    <html>\n    <head>\n    <style>\n    @page {{ size:A4; margin:.45in; }}\n\n    body {{\n        font-family: Arial, sans-serif;\n        font-size: 14pt;\n        line-height: 1.35;\n    }}\n\n    .card {{\n        border:1px solid #dddddd;\n        border-radius:12px;\n        padding:12px 14px;\n        background:#fafafa;\n        margin-bottom:12px;\n        width:100%;\n    }}\n\n    .title {{\n        font-weight:bold;\n        font-size:12pt;\n        margin-bottom:6px;\n    }}\n\n    .paragraph-text {{\n        white-space: normal;\n        line-height: 1.5;\n    }}\n\n    /* 🔥 mark highlight (no padding = stable) */\n    mark.hl {{\n        padding:3px 0;\n        border-radius:5px;\n        box-decoration-break:clone;\n        -webkit-box-decoration-break:clone;\n    }}\n\n    .color-box {{\n        display:inline-block;\n        width:26px;\n        height:14px;\n        border-radius:4px;\n        margin-right:6px;\n        vertical-align:middle;\n    }}\n    </style>\n    </head>\n\n    <body>\n\n    <div class="card">\n    <div class="title">Analysis notes:</div>\n    This PDF contains your text color‐coded according to overall speech quality as measured by the oollim scoring system.\n    Try to improve your <span style="background:#b7e4c7;border-radius:6px;padding:2px 4px;">intonation, emphasis, and word/phrase stress</span> (collectively called prosody) to achieve higher levels of speech quality.\n    </div>\n\n    \n\n    <div class="card">\n    <div class="title">Speech Quality and Color Scoring System:</div>\n    <span class="color-box" style="background:#b7e4c7;"></span> Prosody > 85<br>\n    <span class="color-box" style="background:#ffe8a1;"></span> Prosody > 80<br>\n    <span class="color-box" style="background:#f7c6a3;"></span> Prosody > 75<br>\n    <span class="color-box" style="background:#f5a3a3;"></span> Prosody ≤ 75\n    </div>\n\n    <div class="card">\n    <div class="title">Your text:</div>\n    <div class="paragraph-text">{paragraph_html}</div>\n    </div>\n\n    </body>\n    </html>\n    '

def word_heatmap_html(words_html, c95="#b7e4c7", c90="#ffe8a1", c80="#f7c6a3", c0="#f5a3a3"):
    return f'\n    <html>\n    <head>\n    <style>\n    @page {{ size:A4; margin:.45in; }}\n\n    body {{\n        font-family: Arial, sans-serif;\n        font-size: 14pt;\n        line-height: 1.35;\n    }}\n\n    .card {{\n        border:1px solid #dddddd;\n        border-radius:12px;\n        padding:12px 14px;\n        background:#fafafa;\n        margin-bottom:12px;\n        width:100%;\n    }}\n\n    .title {{\n        font-weight:bold;\n        font-size:12pt;\n        margin-bottom:6px;\n    }}\n\n    .hl-word {{\n        border-radius:6px;\n        padding:2px 5px;\n        box-decoration-break:clone;\n        -webkit-box-decoration-break:clone;\n    }}\n\n    .color-box {{\n        display:inline-block;\n        width:26px;\n        height:14px;\n        border-radius:4px;\n        margin-right:6px;\n        vertical-align:middle;\n    }}\n    </style>\n    </head>\n\n    <body>\n\n    <div class="card">\n    <div class="title">Analysis notes:</div>\n    This PDF contains your text color‐coded according to pronunciation accuracy as measured by the oollim scoring system (experimental, uncalibrated phone-support scores).\n    Try to improve your <span style="background:#b7e4c7;border-radius:6px;padding:2px 4px;">consonant sounds and vowel sounds</span> to achieve higher levels of speech quality.\n    </div>\n\n    \n\n    <div class="card">\n    <div class="title">Word Accuracy and Color Scoring System:</div>\n    <span class="color-box" style="background:{c95};"></span> Accuracy > 95<br>\n    <span class="color-box" style="background:{c90};"></span> Accuracy > 90<br>\n    <span class="color-box" style="background:{c80};"></span> Accuracy > 80<br>\n    <span class="color-box" style="background:{c0};"></span> Accuracy ≤ 80\n    </div>\n\n    <div class="card">\n    <div class="title">Your words:</div>\n    {words_html}\n    </div>\n\n    </body>\n    </html>\n    '
